import "server-only";
import { Role } from "@/generated/prisma/enums";
import { NotFoundError, ValidationError } from "@/lib/errors";
import { AuditAction, recordAudit } from "../audit";
import { generateExamCode, LEARNER_PASSWORD_LENGTH } from "../auth/exam-code";
import { hashPassword } from "../auth/password";
import type { SessionUser } from "../auth/session";
import { assertAdmin } from "../authz";
import { db } from "../db";

/*
 * Learner passwords: one per learner (User.passwordHash, bcrypt), for all of their assigned
 * assessments. Generated by an administrator and returned in plain text only from these calls, to
 * hand out once; only the hash is stored. Assignment, not the password, decides which assessments
 * a learner can open.
 */

export interface IssuedLearnerPassword {
  learner: { id: string; name: string; email: string };
  /** Plain password. Returned only here, once. */
  password: string;
}

async function setPasswords(actor: SessionUser, learners: { id: string; name: string; email: string; hasPassword: boolean }[], context: Record<string, unknown>) {
  // bcrypt is slow on purpose; hash outside the transaction.
  const issued = await Promise.all(
    learners.map(async (l) => {
      const password = generateExamCode(LEARNER_PASSWORD_LENGTH);
      return { learner: { id: l.id, name: l.name, email: l.email }, password, hash: await hashPassword(password), reset: l.hasPassword };
    }),
  );
  await db.$transaction(async (tx) => {
    for (const i of issued) {
      await tx.user.update({ where: { id: i.learner.id }, data: { passwordHash: i.hash } });
      // A reset replaces a password the learner may be signed in with: those sessions end. A first
      // password leaves sessions alone (e.g. a learner mid-exam with a legacy exam password).
      if (i.reset) await tx.session.deleteMany({ where: { userId: i.learner.id } });
    }
    if (issued.length) {
      await recordAudit(
        {
          actorId: actor.id,
          action: AuditAction.LEARNER_PASSWORD_ISSUED,
          entityType: "User",
          entityId: issued.length === 1 ? issued[0].learner.id : undefined,
          metadata: { ...context, count: issued.length, reset: issued.filter((i) => i.reset).length },
        },
        tx,
      );
    }
  });
  return issued.map(({ learner, password }): IssuedLearnerPassword => ({ learner, password }));
}

/**
 * Passwords for the candidates of an assessment: by default only learners who don't have one yet
 * (a learner's password is shared by all their assessments, so it is never changed silently); with
 * `reset`, a new password for every candidate (their old one stops working and they are signed out).
 */
export async function issueLearnerPasswords(actor: SessionUser, assessmentId: string, options: { reset?: boolean } = {}) {
  assertAdmin(actor);
  const assessment = await db.assessment.findUnique({ where: { id: assessmentId }, select: { id: true } });
  if (!assessment) throw new NotFoundError("Assessment not found.");
  const candidates = await db.assessmentCandidate.findMany({
    where: { assessmentId },
    select: { learner: { select: { id: true, name: true, email: true, role: true, passwordHash: true } } },
  });
  if (candidates.length === 0) throw new ValidationError("Assign learners to this assessment before issuing passwords.");
  const learners = candidates
    .map((c) => c.learner)
    .filter((l) => l.role === Role.LEARNER && (options.reset || !l.passwordHash))
    .map((l) => ({ id: l.id, name: l.name, email: l.email, hasPassword: !!l.passwordHash }));
  return setPasswords(actor, learners, { assessmentId, reset: !!options.reset });
}

/** A new password for one learner (their old one stops working and they are signed out). */
export async function resetLearnerPassword(actor: SessionUser, learnerId: string) {
  assertAdmin(actor);
  const l = await db.user.findUnique({ where: { id: learnerId }, select: { id: true, name: true, email: true, role: true, passwordHash: true } });
  if (!l || l.role !== Role.LEARNER) throw new NotFoundError("Learner not found.");
  const [issued] = await setPasswords(actor, [{ id: l.id, name: l.name, email: l.email, hasPassword: !!l.passwordHash }], {});
  return issued;
}

/** Whether each learner has a password, and when they last signed in with it (never the hash). */
export async function learnerPasswordStatus(actor: SessionUser, learnerIds: string[]) {
  assertAdmin(actor);
  const rows = await db.user.findMany({ where: { id: { in: learnerIds }, role: Role.LEARNER }, select: { id: true, passwordHash: true, lastLoginAt: true } });
  return new Map(rows.map((r) => [r.id, { hasPassword: !!r.passwordHash, lastLoginAt: r.lastLoginAt }]));
}
